contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address target, uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);
        require(target != address(c));

        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeC = address(c).balance;

        bool sent;
        c.sendMoney(target, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { sent = false; } else { sent = true; }

        uint afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterC = address(c).balance;

        assert(
            afterCount == beforeCount &&
            ((sent && afterC == beforeC - amount) || (!sent && afterC == beforeC))
        );
    }

    receive() external payable {}
}

